// MODZ: the one pane that opens by itself (DESIGN.md §9). It lists every mod's pane with the
// mod's own live line, and asks the owning mod to open its pane when a row is pressed. The hub,
// its catalog ("Modlar") and every mod's pane take turns in one panel (kit/stage.ts): whichever
// opens last is the one shown, the rest close, so they never pile up as tabs.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { HubCard } from '../types'
import { autoUpdateSettings, installOf } from './auto-update'
import type { Drawing } from './draw'
import { linkCheck, loadCatalog, marketRoot } from './catalog'
import type { Market } from './catalog'
import { footerTree, isHubShown } from './footer'
import { cardOf, focusOf, hiddenRowsOf, MODS_PANE, modsTitle, presenceOf, rowsOf } from './hub'
import { hubTree } from './hub-pane'
import type { HubActions } from './hub-pane'
import { EMPTY_LAYOUT, layoutOf, moveUp, setHidden } from './layout'
import type { HubLayout } from './layout'
import { setLang } from './kit/lang'
import { HUB_PANE, paneOf } from './kit/stage'
import { isSame } from './kit/same'
import { pinned } from './kit/pin'
import { stableDrawings } from './kit/stable'
import { modzTree } from './pane'
import { themeOf } from './theme'
import type { Theme } from './theme'
import { hubWords } from './words'

const PANE = HUB_PANE
const TITLE = 'MODZ'

const OPEN = { plugin: 'modz', key: 'open' } as const
const STAGE = { plugin: 'modz', key: 'stage' } as const
const cardsAtom = atom({ plugin: 'modz', key: 'cards' } as const, {} as Record<string, HubCard>)
// The person's arrangement, mirrored from `$.store` (kept across sessions) so a change redraws the hub.
const layoutAtom = atom({ plugin: 'modz', key: 'layout' } as const, EMPTY_LAYOUT)
const editingAtom = atom({ plugin: 'modz', key: 'isEditing' } as const, false)
const ON = { plugin: 'modz', key: 'isOn' } as const
const LAYOUT_KEY = 'layout'
const DEFAULT_COLUMNS = 80

async function themeNow($: EngineInterface): Promise<Theme> {
  const rows = await $.config.list().catch(() => [])

  return themeOf(rows.find(row => row.key === 'theme')?.value)
}

async function enabledPlugins($: EngineInterface): Promise<Record<string, unknown>> {
  try {
    const value = (await $.settings.read()).enabledPlugins

    return typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : {}
  } catch {
    $.ui.log('modz: settings could not be read; enabled state unknown', { to: 'debug' })

    return {}
  }
}

// Mods are enabled by a skills-folder symlink (~/.claude/skills, or the project's
// .claude/skills in a cloud session), which settings never mention.
async function skillLinks($: EngineInterface): Promise<(name: string) => Promise<boolean>> {
  const home = await $.env.get('HOME').catch(() => undefined)
  const cwd = await $.session.cwd().catch(() => undefined)

  return linkCheck({ roots: [home, cwd], exists: path => $.fs.exists(path) })
}

// A catalog that cannot be read is an empty one: the hub still draws (the engine closes a pane whose drawing
// throws, and the person would lose the way back to every other pane).
async function marketOf($: EngineInterface): Promise<Market> {
  try {
    const stat = await $.fs.stat($.plugin.root, { resolve: true }).catch(() => undefined)
    const root = marketRoot(stat?.realPath ?? $.plugin.root)

    return await loadCatalog({ read: path => $.fs.read(path), root, enabledPlugins: await enabledPlugins($), hasLink: await skillLinks($) })
  } catch (cause) {
    $.ui.log(`modz: the catalog could not be read: ${String(cause)}`, { to: 'debug' })

    return { name: '', mods: [] }
  }
}

// The hub's and the catalog's drawings, kept per what they show (stable.ts); forgotten when the pane opens again.
const hubDrawings = stableDrawings<Drawing>()
const catalogDrawings = stableDrawings<Drawing>()

// A pane that will not close is logged, never thrown: the one being shown is already up.
const closeQuietly = ($: EngineInterface, id: string) =>
  $.ui.close({ id }).catch(cause => $.ui.log(`modz: ${id} could not be closed: ${String(cause)}`, { to: 'debug' }))

// Puts one of the hub's own panes in the panel and closes the other; every mod's open pane closes too.
// The footer toggle opens it without the keyboard (footer.tsx): the composer keeps it.
async function show($: EngineInterface, pane: typeof PANE | typeof MODS_PANE, isFocused = true): Promise<void> {
  const title = pane === PANE ? TITLE : modsTitle()
  const drawings = pane === PANE ? hubDrawings : catalogDrawings
  drawings.reset()
  await $.ui.open(isFocused ? { id: pane, title, focus: true } : { id: pane, title })
  await $.state.set(STAGE, { pane, at: Date.now() })
  await closeQuietly($, pane === PANE ? MODS_PANE : PANE)
}

const openHub = ($: EngineInterface) => show($, PANE)

// The footer toggle (footer.tsx): the hub's panes away when one is shown, else the hub on stage without the keyboard.
async function toggleHub($: EngineInterface): Promise<void> {
  if (!isHubShown(await $.ui.panes())) return show($, PANE, false)
  await closeQuietly($, PANE)
  await closeQuietly($, MODS_PANE)
}

async function saveLayout($: EngineInterface, change: (layout: HubLayout) => HubLayout): Promise<void> {
  const next = change(await read($, layoutAtom))
  await update($, layoutAtom, () => next)
  await $.store.set(LAYOUT_KEY, next)
}

// Each press of the hub, written where it is kept; a failed write is logged, never thrown into the drawing.
// The press waits for the work, so the panel has swapped by the time it settles.
function actionsOf($: EngineInterface): HubActions {
  const run = (what: string, work: () => Promise<unknown>) =>
    work().catch(cause => $.ui.log(`modz: ${what} failed: ${String(cause)}`, { to: 'debug' }))

  return {
    onOpen: pane => run(`opening ${pane}`, () => openPane($, pane)),
    onEdit: isEditing => run('customizing', () => update($, editingAtom, () => isEditing)),
    onMove: opts => run('moving a row', () => saveLayout($, layout => moveUp(layout, opts))),
    onHide: opts => run('hiding a row', () => saveLayout($, layout => setHidden(layout, opts))),
    onReset: () => run('resetting the hub', () => saveLayout($, () => EMPTY_LAYOUT)),
  }
}

// A row press puts that pane in the panel: the catalog is this mod's own pane; any other is its
// mod's to open, asked through `modz.open`. The hub steps aside once the mod says its pane is
// shown, so a mod that does not answer leaves the hub where it is rather than an empty panel.
async function openPane($: EngineInterface, pane: string): Promise<void> {
  if (pane === MODS_PANE) {
    await show($, MODS_PANE)

    return
  }
  answered = null
  await $.state.set(OPEN, { pane, at: Date.now() })
  // The mod answered inside this write, where the engine hands the hub's own hook no event (`.catch`, re-entry).
  if (answered !== null) await stepAside($, answered)
}

// The pane a mod said it opened while the hub's own write was still running; read once that write settles.
let answered: string | null = null

// A mod's pane holds the panel: the hub's panes close and every other mod's pane follows (kit/stage.ts).
async function stepAside($: EngineInterface, pane: string): Promise<void> {
  answered = null
  await $.state.set(STAGE, { pane, at: Date.now() })
  await closeQuietly($, PANE)
  await closeQuietly($, MODS_PANE)
}

// An empty catalog is one that could not be read: the hub says so rather than "0 mods on".
function metaOf(market: Market): string {
  if (market.mods.length === 0) return hubWords().unreadable
  const on = market.mods.filter(mod => mod.isEnabled === true).length

  return hubWords().modsOn(on)
}

async function textOf($: EngineInterface, path: string): Promise<string | undefined> {
  return (await $.fs.exists(path)) ? String(await $.fs.read(path)) : undefined
}

// Turns on Claude Code's own auto-update for the marketplace this copy was installed from (auto-update.ts).
async function keepUpdated($: EngineInterface): Promise<void> {
  const install = installOf($.plugin.root)
  if (install === undefined) return
  const configDir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${await $.env.get('HOME')}/.claude`
  const settingsPath = `${configDir}/settings.json`
  const next = autoUpdateSettings({
    market: install.market,
    settingsText: await textOf($, settingsPath),
    knownText: await textOf($, `${install.pluginsDir}/known_marketplaces.json`),
  })
  if (next === undefined) return
  await $.fs.write(settingsPath, next)
  $.ui.log(`modz: auto-update turned on for the ${install.market} marketplace`, { to: 'debug' })
}

type On = Parameters<Register>[0]
type Options = Parameters<Register>[1]

function hubHooks(on: On, options: Options): void {
  on('session.start', async ($, e, next) => {
    // The interface language (kit/lang.ts). Spelled out: the engine admits an env read by a literal name only.
    setLang(await $.env.get('MODZ_LANG').catch(() => undefined))
    const started = await next(e)
    const saved = layoutOf(await $.store.get(LAYOUT_KEY).catch(() => undefined))
    await update($, layoutAtom, () => saved)
    await $.state.set(ON, true)
    await $.command.register({ name: 'modz', description: hubWords().command })
    if (options.openOnStart !== false) {
      hubDrawings.reset()
      await $.ui.open({ id: PANE, title: TITLE })
    }
    if (options.keepUpdated !== false) {
      void keepUpdated($).catch(cause => $.ui.log(`modz: auto-update could not be turned on: ${String(cause)}`, { to: 'debug' }))
    }

    return started
  })

  // Every mod reports its line under its own `hub` key; the hub keeps the latest of each.
  on('state.set', { key: 'hub' }, async ($, e, next) => {
    const done = await next(e)
    const card = cardOf(e.value)
    // Widened from the declared reporters: the hub also hears a mod it does not list, and never itself.
    const from: string = e.plugin
    if (card === null || from === 'modz') return done
    // An unchanged card is not kept again: the write would redraw the hub for nothing.
    if (isSame((await read($, cardsAtom))[from], card)) return done
    await update($, cardsAtom, cards => ({ ...cards, [from]: card }))

    return done
  }).catch(($, e, next) => next(e))

  // A mod's "MODZ" button: the hub comes forward, and opens again if it was closed. Any mod may ask.
  // The hub comes back once the mod's write has settled: inside it, the mod's own hooks hear nothing (re-entry),
  // so its pane would miss the stage and stay behind as a tab.
  on('state.set', { key: 'home' }, async ($, e, next) => {
    const done = await next(e)
    const from: string = e.plugin
    if (from !== 'modz') {
      $.clock.after(0, () => void openHub($).catch(cause => $.ui.log(`modz: the hub could not come back: ${String(cause)}`, { to: 'debug' })))
    }

    return done
  }).catch(($, e, next) => next(e))

  // A mod's pane is open: it takes the panel. Said inside the hub's own open request, the engine runs only the
  // `.catch` (re-entry, where `$` is closed), which notes the pane for `openPane` to act on once its write settles.
  on('state.set', { key: 'shown' }, async ($, e, next) => {
    const done = await next(e)
    const from: string = e.plugin
    const pane = paneOf(e.value)
    if (from !== 'modz' && pane !== null) await stepAside($, pane)

    return done
  }).catch(($, e, next) => {
    const from: string = e.plugin
    if (next.error.kind === 're-entry' && from !== 'modz') answered = paneOf(e.value) ?? answered

    return next(e)
  })

  on('command.run', { command: 'modz' }, async $ => {
    await openHub($)

    return { text: hubWords().opened }
  })
}

function paneHooks(on: On): void {
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const market = await marketOf($)
    const theme = await themeNow($)
    const columns = e.props.bodyColumns || e.viewport?.columns || DEFAULT_COLUMNS
    const [cards, layout, isEditing] = [await read($, cardsAtom), await read($, layoutAtom), await read($, editingAtom)]
    const presence = presenceOf(market)
    const rows = rowsOf(cards, presence, layout)
    const view = { rows, hidden: hiddenRowsOf(cards, presence, layout), focus: focusOf(rows), meta: metaOf(market), isEditing }

    return pinned(e, hubTree(ui, { ...view, surface: e.surface, columns, theme, actions: actionsOf($), stable: hubDrawings }))
  })

  on('ui.render', { component: 'Pane', requestId: MODS_PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const columns = e.props.bodyColumns || e.viewport?.columns || DEFAULT_COLUMNS

    const onHome = () => void openHub($).catch(cause => $.ui.log(`modz: the hub could not be opened: ${String(cause)}`, { to: 'debug' }))

    return pinned(e, modzTree(ui, { market: await marketOf($), surface: e.surface, columns, theme: await themeNow($), onHome, stable: catalogDrawings }))
  })
}

// The desktop only: the terminal keeps its footer as the engine draws it, and /modz.
function footerHooks(on: On): void {
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    if (e.surface !== 'desktop') return next(e)
    const onPress = () => void toggleHub($).catch(cause => $.ui.log(`modz: the footer toggle failed: ${String(cause)}`, { to: 'debug' }))

    return pinned(e, footerTree($.ui.resolve(e), { modes: e.props.modes, onPress }))
  })
}

export const register: Register = (on, options) => {
  hubHooks(on, options)
  paneHooks(on)
  footerHooks(on)
}

files.hooks/auto-update.ts:
// Keeps every installed mod current at no cost: Claude Code's own background auto-update refreshes a
// marketplace and every plugin installed from it, transceiver's own repo included, but it is off for a
// third-party marketplace until someone turns it on. The hub turns it on once, in the user settings
// entry the engine reads first, and never touches a choice the person already made there.

type Json = Record<string, unknown>

export type UpdatePlan = {
  // The marketplace's name, as `plugin@marketplace` ends.
  market: string
  // The user settings file's text, or undefined when there is none.
  settingsText: string | undefined
  // known_marketplaces.json's text: where the marketplace came from when settings do not say.
  knownText: string | undefined
}

// A marketplace read from a local folder loads in place and is always current; nothing to update.
const LOCAL_SOURCES = new Set(['directory', 'file'])

function isRecord(value: unknown): value is Json {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function parsed(text: string | undefined): Json | undefined {
  if (text === undefined || text.trim() === '') return {}
  try {
    const value: unknown = JSON.parse(text)

    return isRecord(value) ? value : undefined
  } catch {
    return undefined
  }
}

function isRemote(source: unknown): boolean {
  return isRecord(source) && typeof source.source === 'string' && !LOCAL_SOURCES.has(source.source)
}

// The settings entry to write, or undefined when there is nothing to change.
function entryOf(plan: UpdatePlan, declared: unknown): Json | undefined {
  if (isRecord(declared)) {
    if ('autoUpdate' in declared || !isRemote(declared.source)) return undefined

    return { ...declared, autoUpdate: true }
  }
  const known = parsed(plan.knownText)?.[plan.market]
  const source = isRecord(known) ? known.source : undefined

  return isRemote(source) ? { source, autoUpdate: true } : undefined
}

// The new settings text, or undefined to leave the file as it is (unreadable settings included).
export function autoUpdateSettings(plan: UpdatePlan): string | undefined {
  const settings = parsed(plan.settingsText)
  if (settings === undefined || plan.market === '') return undefined
  const markets = isRecord(settings.extraKnownMarketplaces) ? settings.extraKnownMarketplaces : {}
  const entry = entryOf(plan, markets[plan.market])
  if (entry === undefined) return undefined

  return `${JSON.stringify({ ...settings, extraKnownMarketplaces: { ...markets, [plan.market]: entry } }, null, 2)}\n`
}

// An installed copy lives at <plugins>/cache/<marketplace>/<plugin>/<version>.
const CACHED = /^(.*)\/cache\/([^/]+)\/[^/]+\/[^/]+\/?$/

// The marketplace a cached install came from and the plugins folder holding known_marketplaces.json;
// undefined for a copy that loads in place (a skills link, a --plugin-dir, a checkout): always current.
export function installOf(root: string): { market: string; pluginsDir: string } | undefined {
  const match = CACHED.exec(root.replaceAll('\\', '/'))
  if (match?.[1] === undefined || match[2] === undefined) return undefined

  return { pluginsDir: match[1], market: match[2] }
}

files.hooks/draw.ts:
// The desktop pane's Svg: the head, a group's eyebrow and one row per mod (monogram tile, name,
// version pill, health dot, one line of description and a quiet line of surfaces and source).
import type { ModInfo } from './catalog'
import { upper } from './kit/lang'
import { eyebrowWidth } from './kit/svg-text'
import { textWidth } from './kit/svg-metrics'
import { monogram } from './meta'
import type { Group } from './meta'
import { entering, MOTION_CSS } from './kit/motion'
import type { Cue } from './kit/motion'
import { svgDoc } from './theme'
import type { RoleName, Theme } from './theme'
import { catalogWords, placeLine } from './words'

export type Drawing = { source: string; alt: string; height: number }

// A catalog drawing's cue as the catalog opens (motion.ts); absent, it is drawn still.
const settled = (spec: { width: number; height: number; theme: Theme; body: string; cue?: Cue }) =>
  spec.cue === undefined
    ? svgDoc(spec)
    : svgDoc({ width: spec.width, height: spec.height, theme: spec.theme, body: entering(spec.body, spec.cue), css: MOTION_CSS })

const HEAD = 48
const GROUP = 22
const ROW = 66
const TILE = 36
const TEXT_X = TILE + 12
const PILL = 18
export const PILL_HEIGHT = PILL
const PILL_PAD = 8
const GAP = 6
const NOTCH = 6
const DOT_ROOM = 16

export function esc(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

const MONO_EM = 0.6
const WEIGHT_BODY = 500

// Measured SF Pro advances (the kit's table), so a badge sits right after the name it follows.
export function measure(text: string, size: number, weight = WEIGHT_BODY): number {
  return textWidth(text, size, weight)
}

const monoMeasure = (text: string, size: number): number => [...text].length * size * MONO_EM

export function fit(text: string, width: number, font: { size: number; weight?: number }): string {
  const { size, weight = WEIGHT_BODY } = font
  if (measure(text, size, weight) <= width) return text
  const chars = [...text]
  while (chars.length > 1 && measure(`${chars.join('').trimEnd()}…`, size, weight) > width) chars.pop()

  return `${chars.join('').trimEnd()}…`
}

export function eyebrow(spec: { y: number; width: number; label: string; role: RoleName | null; meta: string }): string {
  const label = upper(spec.label)
  const end = NOTCH + 6 + eyebrowWidth(label)
  const metaStart = spec.width - measure(spec.meta, 12)
  const notch = spec.role === null ? 'f-strong' : `fg-${spec.role}`
  const rule = metaStart - end > 24 ? `<rect x="${end + 8}" y="${spec.y - 4}" width="${metaStart - end - 16}" height="1" class="f-line"/>` : ''

  return `<rect x="0.5" y="${spec.y - 7.5}" width="${NOTCH}" height="${NOTCH}" rx="1.5" class="${notch}"/><text x="${NOTCH + 6.5}" y="${spec.y}" class="eb ${spec.role === null ? 'lo' : `fg-${spec.role}`}">${esc(label)}</text>${rule}<text x="${spec.width}" y="${spec.y}" text-anchor="end" class="lb lo">${esc(spec.meta)}</text>`
}

type PillSpec = { right: number; y: number; text: string; role: RoleName | null; isMono?: boolean; isLeft?: boolean }

// A badge whose right edge is at `right` (its left edge, given `isLeft`); neutral without a role.
export function pill(spec: PillSpec): { svg: string; width: number } {
  const textSize = spec.isMono === true ? monoMeasure(spec.text, 10.5) : measure(spec.text, 10.5, 600)
  const width = Math.ceil(textSize + PILL_PAD * 2)
  const x = spec.isLeft === true ? spec.right : spec.right - width
  const frame = spec.role === null ? 'inset line' : `bg-${spec.role} ln-${spec.role}`
  const ink = spec.role === null ? 'mid' : `fg-${spec.role}`
  const font = spec.isMono === true ? ' num' : ''

  return {
    svg: `<rect x="${x + 0.5}" y="${spec.y + 0.5}" width="${width - 1}" height="${PILL - 1}" rx="${PILL / 2}" class="${frame}"/><text x="${x + width / 2}" y="${spec.y + 12.5}" text-anchor="middle" style="font-size:10.5px;font-weight:600" class="${ink}${font}">${esc(spec.text)}</text>`,
    width,
  }
}

export function headSvg(spec: { width: number; theme: Theme; title: string; meta: string; metaRole: RoleName | null; cue?: Cue }): Drawing {
  const meta = spec.meta === '' ? '' : `<text x="${spec.width}" y="40" text-anchor="end" class="lb ${spec.metaRole === null ? 'lo' : `fg-${spec.metaRole}`}">${esc(spec.meta)}</text>`
  const title = fit(spec.title, spec.width - measure(spec.meta, 12) - GAP * 2, { size: 17, weight: 620 })
  const allMods = catalogWords().allMods
  const body = eyebrow({ y: 12, width: spec.width, label: allMods, role: 'edit', meta: '' }) + `<text x="0" y="40" class="hl hi">${esc(title)}</text>${meta}`

  return { source: settled({ width: spec.width, height: HEAD, theme: spec.theme, body, cue: spec.cue }), alt: `${allMods}: ${spec.title}${spec.meta === '' ? '' : ` · ${spec.meta}`}`, height: HEAD }
}

// Each group keeps one colour, on its eyebrow notch and on every monogram tile beneath it.
export const GROUP_ROLE: Record<Group, RoleName | null> = { look: 'edit', safety: 'ok', meter: 'read', flow: 'run', other: null }

export function groupSvg(spec: { width: number; theme: Theme; group: Group; count: number; cue?: Cue }): Drawing {
  const words = catalogWords()
  const label = words.groups[spec.group]
  const count = words.mods(spec.count)
  const body = eyebrow({ y: 15, width: spec.width, label, role: GROUP_ROLE[spec.group], meta: count })

  return { source: settled({ width: spec.width, height: GROUP, theme: spec.theme, body, cue: spec.cue }), alt: `${label}: ${count}`, height: GROUP }
}

// The right edge says only what is unusual: a problem or a switched-off mod gets a word,
// an unknown state a dashed ring, and an on mod one quiet green dot.
function stateMark(mod: ModInfo, right: number): { svg: string; width: number } {
  const words = catalogWords()
  if (!mod.isHealthy) return pill({ right, y: 9, text: words.brokenWord, role: 'danger' })
  if (mod.isEnabled === false) return pill({ right, y: 9, text: words.offWord, role: null })
  const cx = right - DOT_ROOM / 2
  if (mod.isEnabled === null) return { svg: `<circle cx="${cx}" cy="18" r="3.5" fill="none" stroke-width="1.3" stroke-dasharray="2 1.6" class="strong"/>`, width: DOT_ROOM }

  return { svg: `<circle cx="${cx}" cy="18" r="3.5" class="fg-ok"/>`, width: DOT_ROOM }
}

function stateLabel(mod: ModInfo): string {
  const words = catalogWords()
  if (!mod.isHealthy) return words.brokenWord
  if (mod.isEnabled === null) return words.stateUnknown

  return mod.isEnabled ? words.onWord : words.offWord
}

function monogramTile(mod: ModInfo): string {
  const role = mod.isHealthy ? GROUP_ROLE[mod.group] : 'danger'
  const top = (ROW - TILE) / 2
  const frame = role === null ? 'inset strong' : `bg-${role} ln-${role}`
  const ink = role === null ? 'mid' : `fg-${role}`
  const fade = mod.isEnabled === false ? ' opacity=".5"' : ''

  return `<g${fade}><rect x="0.5" y="${top + 0.5}" width="${TILE - 1}" height="${TILE - 1}" rx="9" class="${frame}"/><text x="${TILE / 2}" y="${top + 22.5}" text-anchor="middle" style="font-size:13px;font-weight:700;letter-spacing:.04em" class="num ${ink}">${esc(monogram(mod.name))}</text></g>`
}

export function rowSvg(spec: { width: number; theme: Theme; mod: ModInfo; cue?: Cue }): Drawing {
  const { mod, width } = spec
  const mark = stateMark(mod, width)
  // A mod that tracks commits has no version to show, so its row has no pill.
  const versionText = mod.version === null ? '' : `v${mod.version}`
  const versionWidth = versionText === '' ? 0 : monoMeasure(versionText, 10.5) + PILL_PAD * 2
  const nameRoom = width - TEXT_X - mark.width - versionWidth - GAP * 2
  const name = fit(mod.name, nameRoom, { size: 14, weight: 600 })
  const version = versionText === '' ? { svg: '' } : pill({ right: TEXT_X + measure(name, 14, 600) + GAP, y: 9, text: versionText, role: null, isMono: true, isLeft: true })
  const lineRoom = width - TEXT_X - 4
  const body = [
    monogramTile(mod),
    `<text x="${TEXT_X}" y="22" style="font-size:14px;font-weight:600" class="${mod.isEnabled === false ? 'lo' : 'hi'}">${esc(name)}</text>`,
    version.svg,
    mark.svg,
    `<text x="${TEXT_X}" y="41" class="lb ${mod.isHealthy ? 'mid' : 'fg-danger'}">${esc(fit(mod.description, lineRoom, { size: 12 }))}</text>`,
    `<text x="${TEXT_X}" y="58" class="mi lo">${esc(fit(placeLine(mod), lineRoom, { size: 10.5 }))}</text>`,
  ].join('')
  const alt = `${[mod.name, versionText].filter(Boolean).join(' ')} · ${placeLine(mod)} · ${stateLabel(mod)} · ${mod.description}`

  return { source: settled({ width, height: ROW, theme: spec.theme, body, cue: spec.cue }), alt, height: ROW }
}

